 1	/* Linker script for STM32F469NIH6 (2 MB Flash, 320 KB SRAM) */
 2	ENTRY(Reset_Handler)
 3	
 4	MEMORY
 5	{
 6	  FLASH (rx)  : ORIGIN = 0x08000000, LENGTH = 2048K
 7	  RAM   (rwx) : ORIGIN = 0x20000000, LENGTH = 320K
 8	}
 9	
10	_estack = ORIGIN(RAM) + LENGTH(RAM);
11	
12	SECTIONS
13	{
14	  .isr_vector :
15	  {
16	    . = ALIGN(4);
17	    KEEP(*(.isr_vector))
18	    . = ALIGN(4);
19	  } > FLASH
20	
21	  .text :
22	  {
23	    . = ALIGN(4);
24	    *(.text)
25	    *(.text*)
26	    *(.rodata)
27	    *(.rodata*)
28	    . = ALIGN(4);
29	    _etext = .;
30	  } > FLASH
31	
32	  _sidata = LOADADDR(.data);
33	
34	  .data :
35	  {
36	    . = ALIGN(4);
37	    _sdata = .;
38	    *(.data)
39	    *(.data*)
40	    . = ALIGN(4);
41	    _edata = .;
42	  } > RAM AT > FLASH
43	
44	  .bss :
45	  {
46	    . = ALIGN(4);
47	    _sbss = .;
48	    *(.bss)
49	    *(.bss*)
50	    *(COMMON)
51	    . = ALIGN(4);
52	    _ebss = .;
53	  } > RAM
54	
55	  /DISCARD/ :
56	  {
57	    *(.ARM.attributes)
58	  }
59	}

