16	void HardFault_Handler(void)  __attribute__((weak, alias("Default_Handler")));
17	void MemManage_Handler(void)  __attribute__((weak, alias("Default_Handler")));
18	void BusFault_Handler(void)   __attribute__((weak, alias("Default_Handler")));
19	void UsageFault_Handler(void) __attribute__((weak, alias("Default_Handler")));
20	void SVC_Handler(void)        __attribute__((weak, alias("Default_Handler")));
21	void DebugMon_Handler(void)   __attribute__((weak, alias("Default_Handler")));
