26	const uint32_t *vector_table[] = {
27	    (uint32_t *)&_estack,
28	    (uint32_t *)Reset_Handler,
29	    (uint32_t *)NMI_Handler,
30	    (uint32_t *)HardFault_Handler,
31	    (uint32_t *)MemManage_Handler,
32	    (uint32_t *)BusFault_Handler,
33	    (uint32_t *)UsageFault_Handler,
34	    0, 0, 0, 0,
35	    (uint32_t *)SVC_Handler,
36	    (uint32_t *)DebugMon_Handler,
37	    0,
38	    (uint32_t *)PendSV_Handler,
39	    (uint32_t *)SysTick_Handler
40	};
